/// Lossless enum: values Stripe documents plus any value the API
/// adds later, kept in `undocumented` instead of dropped.
public enum AccountCapabilityFutureRequirementsDisabledReason: Sendable, Equatable, Hashable, LosslessEnum {
    case other
    case pausedInactivity
    case pendingOnboarding
    case pendingReview
    case platformDisabled
    case platformPaused
    case rejectedInactivity
    case rejectedOther
    case rejectedUnsupportedBusiness
    case requirementsFieldsNeeded
    case undocumented(String)

    public init(rawValue raw: String) {
        switch raw {
        case "other": self = .other
        case "paused.inactivity": self = .pausedInactivity
        case "pending.onboarding": self = .pendingOnboarding
        case "pending.review": self = .pendingReview
        case "platform_disabled": self = .platformDisabled
        case "platform_paused": self = .platformPaused
        case "rejected.inactivity": self = .rejectedInactivity
        case "rejected.other": self = .rejectedOther
        case "rejected.unsupported_business": self = .rejectedUnsupportedBusiness
        case "requirements.fields_needed": self = .requirementsFieldsNeeded
        default: self = .undocumented(raw)
        }
    }

    public var rawValue: String {
        switch self {
        case .other: return "other"
        case .pausedInactivity: return "paused.inactivity"
        case .pendingOnboarding: return "pending.onboarding"
        case .pendingReview: return "pending.review"
        case .platformDisabled: return "platform_disabled"
        case .platformPaused: return "platform_paused"
        case .rejectedInactivity: return "rejected.inactivity"
        case .rejectedOther: return "rejected.other"
        case .rejectedUnsupportedBusiness: return "rejected.unsupported_business"
        case .requirementsFieldsNeeded: return "requirements.fields_needed"
        case .undocumented(let value): return value
        }
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        self.init(rawValue: try container.decode(String.self))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(rawValue)
    }
}

